<?php defined('ABSPATH') || exit; ?>
<div class="shop-tools"><form role="search" class="shop-search" action="<?php echo esc_url(dc_shop_url()); ?>" method="get"><label class="screen-reader-text" for="product-search">Search digital products</label><?php echo dc_icon('search'); ?><input type="search" id="product-search" name="s" value="<?php echo esc_attr(get_search_query()); ?>" placeholder="Find your next creative tool…"><input type="hidden" name="post_type" value="product"><button type="submit">Search</button></form><nav class="category-filters" aria-label="Product categories"><a href="<?php echo esc_url(dc_shop_url()); ?>" <?php if (is_shop() && !is_search()) echo 'aria-current="page"'; ?>>Everything</a><?php foreach (dc_categories() as $category) : ?><a href="<?php echo esc_url(dc_category_url($category['slug'])); ?>" <?php if (is_product_category($category['slug'])) echo 'aria-current="page"'; ?>><?php echo esc_html($category['title']); ?></a><?php endforeach; ?></nav></div>
